function parse(t){const root=[],st=[{d:-1,c:root}];t.split('\n').filter(l=>l.trim()).forEach(l=>{const d=l.search(/\S/),n={n:l.trim(),c:[]};while(st[st.length-1].d>=d)st.pop();st[st.length-1].c.push(n);st.push({d,c:n.c})});return root}
function sb(ns,pre,lv){return ns.map(n=>{const p=[...pre,n.n],id=slug(p.join('-')),ic=XUI.sbi(n.n,lv);
 if(!n.c.length){LEAF[id]=p;return `<a href="#${id}" data-id="${id}">${ic}<span>${esc(n.n)}</span></a>`}
 return `<div><button class="g" data-g="${id}">${ic}<span>${esc(n.n)}</span><i>›</i></button><div class="sub" id="g-${id}">${sb(n.c,p,lv+1)}</div></div>`}).join('')}
function shell(u,tree){const lk=u.role==='student'||u.role==='parent';LEAF={};LEAF.dashboard=['Dashboard'];
 document.body.className='app'+(lk?' lk':'');
 document.body.innerHTML=`${XUI.header(u)}<div class="sh"><aside class="sb" id="sb">${XUI.sbHead(u)}${sb(tree,[],0)}<div class="th">${Object.keys(TH).map(k=>`<button style="background:${TH[k][0]}" data-t="${k}" aria-label="${k} theme"></button>`).join('')}</div></aside><main class="mn"><div class="bc"><span id="bt"></span></div><div class="pn" id="c"></div><p class="ft">© School Portal ${new Date().getFullYear()}</p></main></div>${XUI.bottom(tree,u)}`;
 window.XTREE=tree;XUI.wire();
 $('#so').onclick=async()=>{await api('logout','POST').catch(()=>{});go('/login.html')};
 document.querySelectorAll('.sb .g').forEach(b=>b.onclick=()=>$('#g-'+b.dataset.g).classList.toggle('open'));
 document.querySelectorAll('.th button').forEach(b=>b.onclick=()=>theme(b.dataset.t))}
const bn=(u,s)=>`<div class="bn"><p>Welcome back</p><h2>${esc(u.full_name)}</h2><p>${s}</p></div>`;
const tile=(h,t,id)=>`<a class="tl" href="#${id}"><h3>${t}</h3></a>`;
async function dash(u){
 if(u.role==='admin'){let s={};try{s=await api('stats')}catch(e){}
  let det={byClass:[]};try{det=await api('stats-detail')}catch(e){}
  let pend=0;try{pend=(await api('lesson-notes')).notes.filter(x=>x.status==='submitted').length}catch(e){}
  return bn(u,'Administration')+(pend?`<p class="ok" style="margin-top:1rem"><a href="#academics-lesson-plan-my-lesson-plan-s">${pend} lesson note(s) waiting for your approval</a></p>`:'')+`<div class="sc">${[['Pupils',s.pupils],['Teachers',s.teachers],['Parents',s.parents],['Classes',s.classes]].map(x=>`<div><b>${x[1]??0}</b><span>${x[0]}</span></div>`).join('')}</div>${det.byClass.length?`<h3 style="margin:1.4rem 0 .6rem">Pupils per class</h3>${bars(det.byClass.map(x=>[x.name,x.n]))}`:''}<h3 style="margin:1.4rem 0 .6rem">Getting started</h3><div class="grid g3" style="margin:0">${tile(0,'1. Create accounts','administration-users-create-user')}${tile(0,'2. Set up classes','tools-configuration-set-classes')}${tile(0,'3. Register pupils','academics-students-register-students-online')}</div>`}
 let pn=0;if(u.role==='teacher'){try{pn=(await api('alerts/pending')).alerts.length}catch(e){}}
 if(u.role==='teacher')return bn(u,'Teacher')+`<div class="grid g3" style="margin:1.4rem 0 0">${tile(0,'Attendance','academics-attendance-mark-attendance')}${pn?tile(0,pn+' absence alert(s) waiting','academics-attendance-absence-alerts'):''}${tile(0,'Load scores','academics-results-load-score-online')}${tile(0,'Lesson plans','academics-lesson-plan-create-lesson-plan')}</div>`;
 return bn(u,'School Portal')+`<div class="grid g3" style="margin:1.4rem 0 0"><div class="tl"><h3>No new notes</h3><p>Notes uploaded by teachers will be displayed here.</p></div><div class="tl"><h3>Your last test score</h3><p>Results will appear here once published.</p></div><div class="tl"><h3>Subject performance</h3><p>A chart will appear when results are in.</p></div></div>`}
