const row=(l,i)=>`<div class="fr"><label>${l}</label>${i}</div>`,opt=(a,v,l)=>`<option value="${a2(v)}">`,a2=x=>x;
function O(a,v,l){return a.map(x=>`<option value="${x[v]}">${esc(x[l])}</option>`).join('')}
