const shrink=(file,max,q,ty)=>new Promise((res,rej)=>{const img=new Image(),fr=new FileReader();fr.onload=()=>{img.onload=()=>{const k=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*k);c.height=Math.round(img.height*k);c.getContext('2d').drawImage(img,0,0,c.width,c.height);res(c.toDataURL(ty||'image/jpeg',q))};img.onerror=()=>rej(new Error('That file is not an image.'));img.src=fr.result};fr.readAsDataURL(file)});
const bars=rs=>{const m=Math.max(1,...rs.map(r=>r[1]));return rs.map(r=>`<div style="display:flex;gap:.6rem;align-items:center;margin:.3rem 0"><span style="width:140px;font-weight:700">${esc(r[0])}</span><div style="flex:1;background:#eef3fb;border-radius:6px"><div style="width:${r[1]/m*100}%;background:var(--pc2);height:20px;border-radius:6px"></div></div><b>${r[1]}</b></div>`).join('')};
