async function vLogo(){const s=(await api('settings')).settings;
 AFTER=()=>[['lg2','logo'],['sg2','signature']].forEach(([id,key])=>$('#'+id).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const v=await shrink(f,300,.9,'image/png');await api('settings','POST',{key,value:v});$('#'+id+'o').innerHTML=`<img src="${v}" style="height:60px"> ${okm('Saved.')}`}catch(x){toast(x.message)}});
 return `<p class="lead">These appear on report cards. Use a clear image (PNG with a plain or transparent background works best).</p>${row('School logo','<input type="file" id="lg2" accept="image/*">')}<div id="lg2o">${s.logo?`<img src="${s.logo}" style="height:60px">`:''}</div>${row('Head teacher signature','<input type="file" id="sg2" accept="image/*">')}<div id="sg2o">${s.signature?`<img src="${s.signature}" style="height:60px">`:''}</div>`}
function vImpS(){AFTER=()=>$('#xf').onsubmit=async e=>{e.preventDefault();const f=$('#xl').files[0];if(!f)return;$('#r').textContent='Reading file…';try{await loadX();const wb=XLSX.read(await f.arrayBuffer()),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{raw:false,defval:''}),d=await api('scores/import','POST',{rows});$('#r').innerHTML=`<p class="ok">${d.added} score row(s) imported.${d.errors.length?'<br>'+d.errors.map(esc).join('<br>'):''}</p>`}catch(x){$('#r').innerHTML=`<p class="err">${esc(x.message)}</p>`}};
 return `<form id="xf"><p class="lead">Bring past results across, for example from Edves. Upload an Excel or CSV file with the columns <b>admission_no, subject, session, term, ca, assignment, exam</b>. Subject names must match your subject list and pupils must already be registered. Up to 500 rows at a time.</p><input type="file" id="xl" accept=".xlsx,.xls,.csv" required><button class="gb">Import</button><div id="r"></div></form>`}
function vBackup(){AFTER=()=>$('#bk3').onclick=async()=>{try{dlf('school-portal-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json',JSON.stringify(await api('backup'),null,1));$('#ok').innerHTML=okm('Backup downloaded. Keep it somewhere safe.')}catch(x){toast(x.message)}};
 return `<p class="lead">Download a full copy of the school's records (accounts without passwords, pupils without photos, scores, attendance, notes and more). Do this regularly, especially before big changes and at the end of each term.</p>${gb('bk3','Download backup')} <span id="ok"></span>`}
async function view(id,p,u){
 if(id==='dashboard')return XUI.dash(u);
 if(id.startsWith('sec-'))return XUI.section(id.slice(4));
 const mt=id.match(/^tools-configuration-(.+)$/);if(mt&&SETF[mt[1]])return vSet(SETF[mt[1]]);
 const V={'tools-configuration-set-classes':vCls,'tools-configuration-set-subject':vSubj,'tools-configuration-set-subjects-for-classes':vCS2,'academics-students-register-students-online':vReg,'academics-students-register-students-excel':vImp,'academics-students-generate-password':vGen,'administration-users-reset-password':vRst,'administration-users-assign-subject-class':vAsg,'academics-attendance-mark-attendance':vMark,'academics-attendance-attendance-summary':vSum,'academics-attendance-absence-alerts':vAlerts,'administration-calendar-calendar':u=>vCal(u,0),'administration-calendar-view-archive':u=>vCal(u,1),'calendar':u=>vCal(u,0),'communications':vInbox,'academics-results-load-score-online':vScore,'academics-results-student-end-of-term-report':vReport2,'tools-configuration-publish-and-lock-result':vPub,'academics-results-comment-bank':vBank,'academics-results-skills-behaviour-and-activities':vRate,'check-results':vCheck,'administration-users-all-users':vUsers,'administration-users-link-parent-to-pupil':vLink,'messages-inbox':vInbox,'messages-send-message':vSend,'messages-sent-messages':vSent,'academics-communication-book':vBook,'communication-book':vBook,'academics-timetable':vTT,'timetable':vTT,'administration-admission':vAdm,'administration-staff':vStaff,'administration-statistics':vStats,'administration-transportation':vTrans,'transport':vTransKid,'academics-results-subject-spreadsheet':u=>vSheet(u,'subject'),'academics-results-class-term-spreadsheet':u=>vSheet(u,'class'),'academics-results-session-spreadsheet':u=>vSheet(u,'session'),'academics-results-class-report-in-batch':vBatch,'academics-results-mid-term-report':vMid,'academics-results-load-score-excel':vXls,'academics-students-promote-students':vPromo,'academics-students-upload-photographs':vPhoto,'tools-configuration-school-logo-and-signature':vLogo,'tools-import-past-results':vImpS,'tools-backup-and-export':vBackup,'early-years-daily-reports':vDaily,'early-years-secure-pickup':vPickup,'health-health-records':vHealth,'daily-reports':vDailyKids,'health':vHealth,'secure-pickup':vPickup,'academics-lesson-plan-my-lesson-plan-s':vNotes,'academics-lesson-plan-create-lesson-plan':vNoteForm,'academics-lesson-plan-lesson-plan-template':vTpl,'academics-homework':vHw,'homework':vHwKids,'notes':vNotesKids,'attendance':vAttChild};
 ['view-all-students','search-student','advance-search','change-student-status','return-students-to-class'].forEach(k=>V['academics-students-'+k]=vStu);
 Object.assign(V,window.EXT||{});
 if(V[id])return V[id](u);
 if(id==='administration-users-create-user')return `<form id="nf" style="background:none;padding:0;border:0"><div class="fr"><label>Full name *</label><input id="fn" required></div><div class="fr"><label>Username *</label><input id="un" required></div><div class="fr"><label>Role *</label><select id="rl"><option>teacher</option><option>parent</option><option>student</option><option>admin</option></select></div><div class="fr"><label>Email address</label><input id="em" type="email"></div><div class="fr"><label>Mobile number</label><input id="ph"></div><button class="gb">Submit</button><p class="err" id="e"></p><div id="r"></div></form>`;
 if(false&&id==='administration-users-all-users'){const d=await api('users');return `<div class="tw"><table class="t"><thead><tr><th>S/N</th><th>Name</th><th>Username</th><th>Role</th></tr></thead><tbody>${d.users.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.full_name)}</td><td>${esc(x.username)}</td><td>${x.role}</td></tr>`).join('')}</tbody></table></div>`}
 return `<h2>${esc((p||[id]).slice(-1)[0])}</h2><p class="lead" style="margin-top:.6rem">This page is not available.</p>`}
function bind(id){if(id!=='administration-users-create-user')return;
 $('#nf').onsubmit=async e=>{e.preventDefault();$('#e').textContent='';try{const d=await api('users','POST',{full_name:$('#fn').value,username:$('#un').value,role:$('#rl').value,email:$('#em').value,phone:$('#ph').value});$('#r').innerHTML=`<p class="ok">Account created.<br>Username: <b>${esc(d.username)}</b><br>Temporary password: <b>${esc(d.temp_password)}</b><br>Shown once. They must change it at first sign-in.</p>`;e.target.reset()}catch(x){$('#e').textContent=x.message}}}
function route(){AFTER=null;const id=(window.__preview?CUR:location.hash.slice(1))||'dashboard',p=LEAF[id];
 document.querySelectorAll('.sb a').forEach(a=>a.classList.toggle('on',a.dataset.id===id));
 document.querySelectorAll('.sb .sub').forEach(s=>{if(id.startsWith(s.id.slice(2)+'-'))s.classList.add('open')});
 $('#bt').textContent=p?p.join(' > '):(XUI.crumb(id)||id.toUpperCase());$('#sb').classList.remove('open');XUI.before(id);
 view(id,p,U).then(h=>{$('#c').innerHTML=h;bind(id);XUI.after(id);if(AFTER){const a=AFTER;AFTER=null;a()}}).catch(x=>{$('#c').innerHTML=`<p class="err">${esc(x.message)}</p>`})}
async function boot(role){let u;try{u=(await api('me')).user}catch(e){go('/login.html');return}
 if(u.role!==role){home(u.role);return}U=u;
 if(u.must_change_password){shell(u,[]);$('#sb').style.display='none';$('#c').innerHTML=`<h2>Choose a new password</h2><p class="lead">Please replace your temporary password to continue.</p><form id="pf" style="max-width:420px;margin-top:1rem;background:none;padding:0;border:0"><label>Current password<input type="password" id="cp" required></label><label>New password (8+ characters)<input type="password" id="np" minlength="8" required></label><button class="gb">Save password</button><p class="err" id="e"></p></form>`;
  $('#pf').onsubmit=async e=>{e.preventDefault();try{await api('change-password','POST',{current:$('#cp').value,new:$('#np').value});home(u.role)}catch(x){$('#e').textContent=x.message}};return}
 if(role==='parent'&&/[?&]reference=/.test(location.search))location.hash='fees';
 shell(u,parse(TREES[role]));route();addEventListener('hashchange',route);document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a)return;e.preventDefault();const id=a.getAttribute('href').slice(1);if(window.__preview){CUR=id;route()}else location.hash=id})}
function login(){$('#f').onsubmit=async e=>{e.preventDefault();try{const d=await api('login','POST',{username:$('#u').value,password:$('#p').value});home(d.role)}catch(x){$('#e').textContent=x.message}}}
function setup(){$('#f').onsubmit=async e=>{e.preventDefault();try{const r=await fetch('/api/setup',{method:'POST',headers:{'content-type':'application/json','x-setup-key':$('#k').value},body:JSON.stringify({full_name:$('#n').value,username:$('#u').value,password:$('#p').value})});const d=await r.json();if(!r.ok)throw new Error(d.error);$('#f').innerHTML='<p class="ok">Admin account created.</p><button type="button" class="btn" onclick="go(\'/login.html\')">Go to sign in</button>'}catch(x){$('#e').textContent=x.message}}}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('button');if(!b||b.type!=='submit'||!b.form||!b.form.onsubmit)return;e.preventDefault();if(b.form.reportValidity&&!b.form.reportValidity())return;b.form.onsubmit({preventDefault(){},target:b.form})});
